package dev.studyforge.banking.cli; import dev.studyforge.banking.application.*; import dev.studyforge.banking.domain.*; import java.time.Clock; import java.util.*; public final class Main { private Main(){} public static void main(String[] args){ BankingCore bank=BankingCore.inMemory(Clock.systemUTC(),UUID::randomUUID,FeeStrategy.noFee(),FeeStrategy.noFee(),List.of(t->System.out.println("Committed "+t.type()+" "+t.amount()))); AccountId id=new AccountId("demo"); bank.open(Account.builder(id,"Demo",Currency.getInstance("USD")).build()); bank.deposit(new Deposit(id,Money.of("10.00","USD"))); System.out.println(bank.account(id).balance()); } }
